INSERT INTO public.trackable_resource_definition (id, slug, name, description, recharge_type, maximum_type, base_maximum, multiplier, minimum_maximum, scaling_ability, custom, created_at, updated_at) VALUES (4, 'utilisations-de-magie-galvanisante', 'Utilisations de Magie galvanisante', NULL, 'long-rest', 'proficiency-bonus', 0, 1, 0, NULL, true, '2026-09-07 22:06:29', '2026-09-07 22:06:29');
